\title{Exact quantum spin liquids with topological order on maple-leaf and trellis lattices}

\author{Li Ern Chern}
\affiliation{Max Planck Institute for the Physics of Complex Systems, 01187 Dresden, Germany}

\author{Roderich Moessner}
\affiliation{Max Planck Institute for the Physics of Complex Systems, 01187 Dresden, Germany}

